import itertools
from math import gcd

def is_good(U):
    if len(U) < 3: return False
    for triple in itertools.combinations(U, 3):
        if gcd(triple[0], gcd(triple[1], triple[2])) != 1:
            return False
    U_list = list(U)
    for i in range(len(U_list)):
        for j in range(i + 1, len(U_list)):
            u_i, u_j = U_list[i], U_list[j]
            found = False
            for k in range(len(U_list)):
                if k == i or k == j: continue
                if (u_i * u_j) % U_list[k] == 0:
                    found = True
                    break
            if not found: return False
    return True

for D in range(1, 41):
    temp_D = D
    primes = []
    d = 2
    while d * d <= temp_D:
        while temp_D % d == 0:
            primes.append(d)
            temp_D //= d
        d += 1
    if temp_D > 1:
        primes.append(temp_D)

    pairs = list(itertools.combinations(range(5), 2))
    for assignment in itertools.product(pairs, repeat=len(primes)):
        U = [1] * 5
        for p, pair in zip(primes, assignment):
            U[pair[0]] *= p
            U[pair[1]] *= p
        if len(set(U)) == 5:
            if is_good(tuple(U)):
                print(f"D={D}, U={U}, m={D*D}")

