import itertools
from math import gcd

def find_good_numbers_n3(max_D):
    good_numbers = set()
    candidates = range(1, 100) 
    for combo in itertools.combinations(candidates, 3):
        d1, d2, d3 = combo
        if gcd(d1, d2) == 1 and gcd(d1, d3) == 1 and gcd(d2, d3) == 1:
            D = d1 * d2 * d3
            good_numbers.add(D*D)
